using System.Drawing.Imaging;
namespace LocalChat;
partial class MainWindow {
 async Task CreateVideo(){
  RequireIdle();if(importing)throw new Exception("Дождись импорта репозитория.");using var files=new OpenFileDialog{Title="Кадры MP4 — PNG/JPEG, до 60; порядок по имени файла",Filter="Изображения|*.png;*.jpg;*.jpeg",Multiselect=true};if(files.ShowDialog(this)!=DialogResult.OK)return;string[] frames=files.FileNames.OrderBy(x=>Path.GetFileName(x),StringComparer.OrdinalIgnoreCase).ToArray();VideoRecipe.Manifest(frames.Length);
  foreach(var f in frames)if(new FileInfo(f).Length>40L*1024*1024)throw new Exception("Один исходный кадр больше 40 МБ.");
  using var binary=new OpenFileDialog{Title="Выбери свой проверенный ffmpeg.exe (отдельная бесплатная программа)",Filter="FFmpeg|ffmpeg.exe"};if(binary.ShowDialog(this)!=DialogResult.OK)return;
  if(!await ConfirmAsync("NORA · локальное видео",$"Создать MP4 из {frames.Length} изображений?\n1280×720 · 24 кадра/с · 3 секунды на изображение · без звука.\nПорядок: по имени файла. Это слайд-шоу, не генерация новых сцен.\n\nБудет запущен выбранный тобой ffmpeg.exe. NORA не проверяет его происхождение. Используй сборку из доверенного источника, указанного на ffmpeg.org/download.html."))return;
  current.Messages.Add(new(){Role="user",Text=$"Создать MP4 из {frames.Length} выбранных изображений"});var response=new Message{Role="assistant",State="streaming"};current.Messages.Add(response);BeginWork(response);busy=true;generation=new();State();Post("busy",true);string temp=Path.Combine(root,"video-temp",Guid.NewGuid().ToString("N"));
  try{Directory.CreateDirectory(temp);SaveCurrent();StopAir();StopServer();RecordWork("Освобождаю ресурсы текстовой модели; подготавливаю кадры");
   await Task.Run(()=>{for(int i=0;i<frames.Length;i++){generation.Token.ThrowIfCancellationRequested();using var image=Image.FromFile(frames[i]);if(image.Width>20000||image.Height>20000)throw new Exception("Размер кадра слишком большой.");using var canvas=new Bitmap(1280,720);using(var g=Graphics.FromImage(canvas)){g.Clear(Color.Black);g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;double k=Math.Min(1280.0/image.Width,720.0/image.Height);int w=Math.Max(1,(int)(image.Width*k)),h=Math.Max(1,(int)(image.Height*k));g.DrawImage(image,(1280-w)/2,(720-h)/2,w,h);}canvas.Save(Path.Combine(temp,$"frame-{i:D3}.png"),ImageFormat.Png);}},generation.Token);
   string manifest=Path.Combine(temp,"frames.ffconcat"),output=Path.Combine(temp,"result.mp4");await File.WriteAllTextAsync(manifest,VideoRecipe.Manifest(frames.Length),new System.Text.UTF8Encoding(false),generation.Token);RecordWork("FFmpeg: кодирование MP4 · "+frames.Length*3+" с");Post("status","Создаю MP4… Кнопка остановки отменит кодирование.");await VideoRecipe.Render(binary.FileName,manifest,output,frames.Length,generation.Token);generation.Token.ThrowIfCancellationRequested();
   var a=new OutputArtifact{Name="NORA-видео-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".mp4",Kind="video",Bytes=new FileInfo(output).Length};a.RelativePath=current.Id+"/"+a.Id+"/"+a.Name;string destination=StoredPath(a);Directory.CreateDirectory(Path.GetDirectoryName(destination)!);File.Move(output,destination);response.Artifacts.Add(a);response.Text=$"MP4 готов: {frames.Length*3} с, 1280×720, без звука. Кадры расположены по имени файла. Это монтаж выбранных изображений, не нейрогенерация.";response.State="complete";RecordWork("MP4 создан и добавлен файлом в чат");
  }catch(OperationCanceledException){response.State="cancelled";response.Text="Создание видео остановлено. Готовый файл не выдан.";}catch(Exception e){response.State="error";response.Text="Не удалось создать видео: "+e.Message;RecordWork("Ошибка видеомонтажа");}
  finally{try{Directory.Delete(temp,true);}catch{}EndWork(response);try{SaveCurrent();}finally{busy=false;generation.Dispose();generation=null;State();Post("busy",false);}}
 }
}
